  <div class="spmb-head"><div><h2>Rekap Pendaftar SPMB <?php echo unit_e($allUnits[$scope]); ?></h2><p class="muted">Seluruh calon siswa di unit ini, dari semua kelas tujuan.</p></div><a class="spmb-export" href="?<?php echo unit_e(http_build_query(['tab'=>'enrollments','unit'=>$scope,'year'=>$filters['year'],'class'=>$filters['class'],'export_spmb'=>1])); ?>">Unduh Excel (.xlsx)</a></div>
  <form class="spmb-filter" method="get"><input type="hidden" name="tab" value="enrollments"><input type="hidden" name="unit" value="<?php echo unit_e($scope); ?>">
    <label>Tahun ajaran<select name="year"><option value="">Semua tahun</option><?php foreach($years as $year): ?><option value="<?php echo unit_e($year); ?>" <?php echo $filters['year']===$year?'selected':''; ?>><?php echo unit_e($year); ?></option><?php endforeach; ?></select></label>
    <label>Kelas tujuan<select name="class"><option value="">Semua kelas</option><?php foreach(spmb_entry_classes($scope) as $class): ?><option value="<?php echo unit_e($class); ?>" <?php echo $filters['class']===$class?'selected':''; ?>><?php echo unit_e($class); ?></option><?php endforeach; ?><option value="Belum ditentukan" <?php echo $filters['class']==='Belum ditentukan'?'selected':''; ?>>Belum ditentukan (data lama)</option></select></label>
