  <div class="spmb-summary"><div><span>Total pendaftar</span><strong><?php echo count($rows); ?></strong></div><?php foreach($counts as $class=>$count): ?><div><span><?php echo unit_e($class); ?></span><strong><?php echo $count; ?></strong></div><?php endforeach; ?></div>
  <div class="spmb-table-wrap"><table class="spmb-table"><thead><tr><th>No</th><th>No. Registrasi</th><th>Calon Siswa</th><th>Kelas Tujuan</th><th>Tahun Ajaran</th><th>Orang Tua</th><th>WhatsApp</th><th>Status</th><th>Daftar</th><th>Aksi</th></tr></thead><tbody>
  <?php foreach($rows as $index=>$row): ?><tr><td><?php echo $index+1; ?></td><td><?php echo unit_e($row['registration_number'] ?: '-'); ?></td><td><strong><?php echo unit_e($row['student_name']); ?></strong></td><td><?php echo unit_e($row['entry_class'] ?: 'Belum ditentukan'); ?></td><td><?php echo unit_e($row['academic_year']); ?><?php if($row['admission_track']==='waiting_list'): ?><br><small>Waiting List</small><?php endif; ?></td><td><?php echo unit_e($row['parent_name']); ?></td><td><a href="tel:<?php echo unit_e(preg_replace('/[^0-9+]/','',$row['whatsapp'])); ?>"><?php echo unit_e($row['whatsapp']); ?></a></td><td><?php echo unit_e($statusLabels[$row['registration_status']] ?? $row['registration_status']); ?></td><td><?php echo unit_e(tanggal_indo($row['created_at'])); ?></td><td><?php if(!empty($row['source'])): ?><span class="muted">Data lama</span><?php else: ?><form method="post"><input type="hidden" name="csrf" value="<?php echo unit_e($csrf); ?>"><input type="hidden" name="action" value="update_spmb_status"><input type="hidden" name="id" value="<?php echo (int)$row['id']; ?>"><select name="status" aria-label="Status <?php echo unit_e($row['student_name']); ?>"><?php foreach($statusLabels as $key=>$label): ?><option value="<?php echo $key; ?>" <?php echo $row['registration_status']===$key?'selected':''; ?>><?php echo unit_e($label); ?></option><?php endforeach; ?></select><button>Simpan</button></form><?php endif; ?></td></tr><?php endforeach; ?>
  <?php if(!$rows): ?><tr><td colspan="10" class="muted">Belum ada pendaftar sesuai filter.</td></tr><?php endif; ?></tbody></table></div>
